import json
# 「넣었는데 바로 안 보임」 조사: 서식·문서함 · 법령·매뉴얼 · 항목 창 서식 · 참고 자료 · 업무 관리 → steps_live.json
# 각 장면에서 「하자마자 보이는 곳」과 「다시 그린 뒤 보이는 곳」을 비교 — 다르면 실시간 표시가 안 되는 곳
P = "(async()=>{try{const W=ms=>new Promise(r=>setTimeout(r,ms));"
E = "}catch(e){return 'ERR '+e.message+' '+(e.stack||'').split('\\n')[1]}})()"
H = ("const pw=()=>app.allData.workflows.find(w=>/소모품 구매/.test(w.title)&&!w.isReference&&!w.isDeleted);"
     "const up=(inp,name,body,type)=>{const dt=new DataTransfer();dt.items.add(new File([body+' %'+name],name,{type}));inp.files=dt.files;inp.dispatchEvent(new Event('change',{bubbles:true}));};"
     "const PDF='%PDF-1.4\\n1 0 obj<<>>endobj\\ntrailer<<>>\\n%%EOF\\n'+'x'.repeat(400);"
     "const has=(sel,n)=>{const e=document.querySelector(sel);return e?(e.textContent.includes(n)?'보임':'안 보임'):'(없음)'};"
     "const cur=()=>{const w=pw();return w.checklist.findIndex(x=>!x.completed&&!x.skipped&&x.indent>0)};"
     "window.confirm=()=>true;const panelOn=()=>{const p=document.getElementById('aiPanel');return p&&!p.classList.contains('hidden')&&app.aiPanelViewMode==='procedure'};"
     "const rowHtml=i=>{const r=[...document.querySelectorAll('.focus-mode [data-index], [data-index]')].find(x=>x.dataset.index==String(i)&&x.offsetParent);return r?r.outerHTML.replace(/\\s+/g,' '):''};")
S = []
def step(label, body): S.append({"label": label, "js": P + H + body + E})

step("준비", "localStorage.setItem('deadlineNotifyMode','off');document.querySelectorAll('.modal.show').forEach(m=>m.classList.remove('show'));app.insertPracticeWorkflows();await W(2500);document.querySelectorAll('.modal.show').forEach(m=>m.classList.remove('show'));return pw()?.title")

# R1 서식·문서함 창에서 올리기 (모든 자료)
step("R1 서식·문서함 · 모든 자료에서 올리기", "await app.openDocumentRepo();await W(800);up(document.getElementById('documentRepoFileInput'),'실시간시험_서식1.pdf',PDF,'application/pdf');await W(2500);const a=has('#documentRepoModal .fb-tbody','실시간시험_서식1');const c=document.querySelector('#documentRepoModal .fb-side').textContent.replace(/\\s+/g,' ').slice(0,80);await app._fbRender('repo');return '바로='+a+' | 다시 그린 뒤='+has('#documentRepoModal .fb-tbody','실시간시험_서식1')+' | 왼쪽='+c")
# R2 폴더 안에서 올리기
step("R2 서식·문서함 · 폴더 안에서 올리기", "const f=app._getDocumentRepoFolders();let fid=f[0]?.id;if(fid==null){app.addDocumentRepoFolder('시험폴더',null);fid=app._getDocumentRepoFolders()[0].id;}app._fbState('repo').folder=fid;await app._fbRender('repo');await W(400);up(document.getElementById('documentRepoFileInput'),'실시간시험_서식2.pdf',PDF,'application/pdf');await W(2500);const a=has('#documentRepoModal .fb-tbody','실시간시험_서식2');await app._fbRender('repo');return '바로='+a+' | 다시 그린 뒤='+has('#documentRepoModal .fb-tbody','실시간시험_서식2')")
# R3 창 안에 끌어다 놓기
step("R3 서식·문서함 · 끌어다 놓기", "app._fbState('repo').folder='__all__';await app._fbRender('repo');const dt=new DataTransfer();dt.items.add(new File([PDF],'실시간시험_서식3.pdf',{type:'application/pdf'}));const tb=document.querySelector('#documentRepoModal [ondrop]');tb.dispatchEvent(new DragEvent('drop',{bubbles:true,cancelable:true,dataTransfer:dt}));await W(2500);const a=has('#documentRepoModal .fb-tbody','실시간시험_서식3');await app._fbRender('repo');return '놓은 곳='+(tb.className||tb.id)+' | 바로='+a+' | 다시 그린 뒤='+has('#documentRepoModal .fb-tbody','실시간시험_서식3')")
step("R4 서식·문서함 닫기", "app.closeModal('documentRepoModal');await W(400);return 'ok'")

# L1 법령·매뉴얼
step("L1 법령·매뉴얼 · 올리기", "await app.openLawLibrary();await W(800);up(document.getElementById('lawLibraryFileInput'),'실시간시험_법령1.txt','제1조(목적) 이 법은 실시간 표시 시험을 위한 것이다. '.repeat(5),'text/plain');await W(2500);const a=has('#lawLibraryModal .fb-tbody','실시간시험_법령1');await app._fbRender('law');return '바로='+a+' | 다시 그린 뒤='+has('#lawLibraryModal .fb-tbody','실시간시험_법령1')")
step("L2 법령·매뉴얼 · 끌어다 놓기", "const dt=new DataTransfer();dt.items.add(new File(['제2조(정의) 끌어다 놓기 시험. '.repeat(6)],'실시간시험_법령2.txt',{type:'text/plain'}));const tb=document.querySelector('#lawLibraryModal [ondrop]');tb.dispatchEvent(new DragEvent('drop',{bubbles:true,cancelable:true,dataTransfer:dt}));await W(2500);const a=has('#lawLibraryModal .fb-tbody','실시간시험_법령2');await app._fbRender('law');return '바로='+a+' | 다시 그린 뒤='+has('#lawLibraryModal .fb-tbody','실시간시험_법령2')")
step("L3 법령·매뉴얼 닫기", "app.closeModal('lawLibraryModal');await W(400);return 'ok'")

# I 일하는 화면 · 항목 창 서식 탭에서 올리기 (지금 할 일)
step("I0 연습 업무 열기", "app.focusWorkflow(pw().id);await W(1800);const i=cur();return '지금 할 일='+pw().checklist[i].text+' (#'+i+')'")
step("I1 항목 창 서식 탭 · 내 PC에서 올리기", "const w=pw(),i=cur();const r0=rowHtml(i);await app.showChecklistItemModal(w.id,i,'formats');await W(900);const inp=[...document.querySelectorAll('.mat-btns input[type=file]')].find(x=>x.closest('label')?.offsetParent);up(inp,'실시간시험_항목서식.pdf',PDF,'application/pdf');await W(2500);const n='실시간시험_항목서식';const r=['패널 켜짐='+panelOn(),'항목 창='+has('#main-checklist-formats-list-'+w.id+'-'+i,n),'패널='+has('#aiPanelOfflineDashboard',n)];app.closeChecklistItemModal();await W(800);const r1=rowHtml(i);r.push('닫은 뒤 패널='+has('#aiPanelOfflineDashboard',n));r.push('닫은 뒤 줄 바뀜='+(r0!==r1));app.refreshAIPanelDashboardIfNeeded();await W(500);r.push('패널 다시 그린 뒤='+has('#aiPanelOfflineDashboard',n));app.displayWorkflows();await W(1500);r.push('전체 다시 그린 뒤 줄 바뀜(닫은 뒤와 비교)='+(r1!==rowHtml(i)));return r.join(' | ')")
S.append({"shot": "live_i1.png"})
step("I2 항목 창 서식 탭 · 서식·문서함에서 고르기", "const w=pw(),i=cur();await app.showChecklistItemModal(w.id,i,'formats');await W(900);const d=(await app._getAllRepoDocuments()).find(d=>d.name==='실시간시험_서식1.pdf');if(!d)return '서식1 없음: '+(await app._getAllRepoDocuments()).map(x=>x.name).join(',');const it=w.checklist[i];const before=(it.linkedDocs||[]).length;"
     "app.openDocumentPicker(w.id,i);await W(900);const pick=app._fbPicking('repo');if(!pick)return '고르기 창 안 열림';pick.sel.add(d.id);await app._fbRender('repo');const bs=[...document.querySelectorAll('#documentRepoModal button')].filter(b=>b.offsetParent).map(b=>b.textContent.trim()).filter(t=>t&&t.length<20);const ok=[...document.querySelectorAll('#documentRepoModal button.wfm-btn-primary')].find(b=>b.offsetParent&&/연결하기/.test(b.textContent));const btxt=ok?ok.textContent.trim():'(단추 없음: '+bs.join('/')+')';ok&&ok.click();await W(1200);"
     "const n='실시간시험_서식1';const r=['단추='+btxt,'연결 수 '+before+'→'+(it.linkedDocs||[]).length,'항목 창='+has('#main-checklist-formats-list-'+w.id+'-'+i,n),'패널='+has('#aiPanelOfflineDashboard',n)];app.closeChecklistItemModal();await W(800);r.push('닫은 뒤 패널='+has('#aiPanelOfflineDashboard',n));app.refreshAIPanelDashboardIfNeeded();await W(500);r.push('패널 다시 그린 뒤='+has('#aiPanelOfflineDashboard',n));return r.join(' | ')")
step("I3 단계(01 구매 준비) 서식 올리기", "const w=pw();const i=0;await app.showChecklistItemModal(w.id,i,'formats');await W(900);const inp=[...document.querySelectorAll('.mat-btns input[type=file]')].find(x=>x.closest('label')?.offsetParent);up(inp,'실시간시험_단계서식.pdf',PDF,'application/pdf');await W(2500);const n='실시간시험_단계서식';const r=['항목 창='+has('#main-checklist-formats-list-'+w.id+'-'+i,n),'패널='+has('#aiPanelOfflineDashboard',n)];app.closeChecklistItemModal();await W(800);r.push('닫은 뒤 패널='+has('#aiPanelOfflineDashboard',n));app.refreshAIPanelDashboardIfNeeded();await W(500);r.push('패널 다시 그린 뒤='+has('#aiPanelOfflineDashboard',n));return r.join(' | ')")
step("I4 항목 창 업무팁 저장 → 패널", "const w=pw(),i=cur();await app.showChecklistItemModal(w.id,i,'tip');await W(900);const ta=document.getElementById('tip3-body-'+w.id+'-'+i);if(!ta)return '업무팁 칸 없음';ta.focus();ta.value=ta.value+' 실시간시험_업무팁줄';ta.dispatchEvent(new Event('input',{bubbles:true}));ta.blur();await W(800);const n='실시간시험_업무팁줄';const r=['패널='+has('#aiPanelOfflineDashboard',n)];app.closeChecklistItemModal();await W(800);r.push('닫은 뒤 패널='+has('#aiPanelOfflineDashboard',n));return r.join(' | ')")
step("D1 서식·문서함에서 이름 바꾸기 → 패널 · Ctrl+Z", "const d=(await app._getAllRepoDocuments()).find(d=>d.name==='실시간시험_항목서식.pdf');await app._fbRenameDoc('repo',d.id,'실시간시험_새이름');await W(600);const r=['패널 새 이름='+has('#aiPanelOfflineDashboard','실시간시험_새이름')];await app._undoLast();await W(600);r.push('되돌린 뒤 예전 이름='+has('#aiPanelOfflineDashboard','실시간시험_항목서식'));return r.join(' | ')")
step("D2 서식·문서함 「새 판으로 바꾸기」 → 패널", "const d=(await app._getAllRepoDocuments()).find(d=>d.name==='실시간시험_항목서식.pdf');const p=app._fbReplaceVersionWith('repo',d.id,new File([PDF+' 새판'],'실시간시험_항목서식(새판).pdf',{type:'application/pdf'}));await W(800);const b=[...document.querySelectorAll('button')].find(x=>x.offsetParent&&x.textContent.trim()==='새 판으로 바꾸기');if(!b)return '묻는 창 단추 없음';b.click();await p;await W(800);const r=['패널 새 판='+has('#aiPanelOfflineDashboard','실시간시험_항목서식(새판)')];await app._undoLast();await W(800);r.push('되돌린 뒤 예전 판='+(document.getElementById('aiPanelOfflineDashboard').textContent.includes('실시간시험_항목서식.pdf')?'보임':'안 보임'));return r.join(' | ')")
step("D3 서식·문서함에서 지우기 → 패널", "const d=(await app._getAllRepoDocuments()).find(d=>d.name==='실시간시험_항목서식.pdf');await app.deleteRepoDocument(d.id,{silent:true});await W(800);return '지운 뒤 패널='+has('#aiPanelOfflineDashboard','실시간시험_항목서식')")
step("F1 참고 자료 · 올리기(일하는 화면)", "const w=pw();const n='실시간시험_참고';const card=()=>{const c=document.querySelector('.main-layout');return c?c.innerHTML:''};const c0=card();await app._refAddWithToast(w.id,[new File(['제3조 참고 자료 시험. '.repeat(8)],n+'.txt',{type:'text/plain'})]);await W(1500);const c1=card();const linked=(app.checklistDetails['project-'+w.id]?.linkedLibraryDocs||[]).length;app.displayWorkflows();await W(1500);const c2=card();return '연결 수='+linked+' | 바로 화면에 이름='+c1.includes(n)+' | 올린 뒤 화면 바뀜='+(c0!==c1)+' | 다시 그린 뒤 이름='+c2.includes(n)+' | 다시 그리면 또 바뀜='+(c1!==c2)")
step("F2 길잡이에 참고 자료", "const w=pw(),i=cur();await app.showChecklistHelp(w.id,i);await W(1400);const m=[...document.querySelectorAll('[id^=aiGuideModal_]')].filter(x=>/^aiGuideModal_\\d+$/.test(x.id)).pop();const r='길잡이='+(m&&m.textContent.includes('실시간시험_참고')?'보임':'안 보임');document.querySelectorAll('[id^=aiGuideModal_]').forEach(m=>m.querySelector('[id$=_closeBtn]')?.click());await W(400);return r")
# W 업무 관리
step("W0 업무 관리 열기", "app.unfocusWorkflow?.();app.exitFocusMode?.();await W(500);app.openWorkflowManager();await W(900);const rows=()=>document.querySelector('#workflowManagerModal').innerText;return '연습 업무 보임='+rows().includes('소모품 구매')")
WT = "const txt=()=>document.querySelector('#workflowManagerModal').innerText;const sel=id=>{app._wfmSelectedIds.clear();app._wfmSelectedIds.add(id);};const after=async()=>{const a=txt();app.renderWorkflowTree();await W(400);return a===txt()?'같음':'다름(실시간 아님)'};"
step("W1 새 폴더 만들기", WT + "const n0=(app.allData.folders||[]).length;const b=[...document.querySelectorAll('#workflowManagerModal button')].find(x=>/새 폴더/.test(x.textContent)&&x.offsetParent);return '새 폴더 단추='+!!b")
step("W2 레퍼런스로(사본)", WT + "const w=pw();sel(w.id);app.renderWorkflowTree();await W(300);const c0=app.allData.workflows.length;app.wfmBulkSetReference();await W(1500);document.querySelectorAll('.modal.show').forEach(m=>{if(m.id!=='workflowManagerModal'){const p=[...m.querySelectorAll('button')].find(b=>/레퍼런스|만들기|확인/.test(b.textContent)&&/primary/.test(b.className));p&&p.click();}});await W(1200);return '업무 수 '+c0+'→'+app.allData.workflows.length+' | 다시 그리면 '+(await after())")
step("W3 보관 → 되돌리기", WT + "const w=pw();window.__wid=w.id;sel(w.id);app.renderWorkflowTree();await W(300);app.wfmBulkArchive();await W(1500);const ww=()=>app.allData.workflows.find(x=>x.id===window.__wid);const r='보관됨='+!!ww()?.isArchived+' | 다시 그리면 '+(await after());const t=[...document.querySelectorAll('.toast')].map(x=>x.textContent.replace(/\\s+/g,' ').trim()).pop()||'';const u=[...document.querySelectorAll('.toast button, .toast [class*=action], .toast a')].find(b=>/되돌리기|실행 취소/.test(b.textContent));if(u){u.click();await W(1200);return r+' | 알림='+t.slice(0,40)+' | [되돌리기] 뒤 보관='+!!ww()?.isArchived+' · 다시 그리면 '+(await after())}if(app._undoLast){await app._undoLast();await W(1200);return r+' | Ctrl+Z 뒤 보관='+!!ww()?.isArchived+' · 다시 그리면 '+(await after())}return r+' | 알림='+t.slice(0,40)")
step("W4 삭제 → 실행 취소", WT + "const ww=()=>app.allData.workflows.find(x=>x.id===window.__wid);sel(window.__wid);app.renderWorkflowTree();await W(300);app.wfmBulkDelete();await W(1500);const r='지움='+!!ww()?.isDeleted+' | 다시 그리면 '+(await after());const t=[...document.querySelectorAll('.toast')].map(x=>x.textContent.replace(/\\s+/g,' ').trim()).pop()||'';const u=[...document.querySelectorAll('.toast button, .toast [class*=action], .toast a')].find(b=>/되돌리기|실행 취소/.test(b.textContent));if(u){u.click();await W(1200);return r+' | 알림='+t.slice(0,40)+' | [실행 취소] 뒤 지움='+!!ww()?.isDeleted+' · 다시 그리면 '+(await after())}if(app._undoLast){await app._undoLast();await W(1200);return r+' | Ctrl+Z 뒤 지움='+!!ww()?.isDeleted+' · 다시 그리면 '+(await after())}return r+' | 알림='+t.slice(0,40)")
step("W5 이름 바꾸기 → Ctrl+Z", WT + "const ww=()=>app.allData.workflows.find(x=>x.id===window.__wid);const old=ww().title;sel(window.__wid);app.renderWorkflowTree();await W(300);const fn=app.wfmRenameWorkflow||app.renameWorkflowInline||null;document.dispatchEvent(new KeyboardEvent('keydown',{key:'F2',bubbles:true}));await W(500);const ed=document.querySelector('#workflowManagerModal input:focus, #workflowManagerModal [contenteditable=true]');if(!ed)return 'F2 입력칸 없음';if(ed.tagName==='INPUT')ed.value='실시간시험 새 이름';else ed.textContent='실시간시험 새 이름';ed.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true}));await W(800);const r='이름='+ww().title+' | 화면='+(txt().includes('실시간시험 새 이름')?'보임':'안 보임');document.dispatchEvent(new KeyboardEvent('keydown',{key:'z',ctrlKey:true,bubbles:true}));await W(1000);return r+' | Ctrl+Z 뒤 이름='+ww().title+' · 다시 그리면 '+(await after())")
S.append({"shot": "live_w.png"})
step("W6 업무 관리 열린 채 다른 곳에서 업무가 바뀜(창 뒤 새 업무 가져오기)", WT + "const c0=app.allData.workflows.length;app.insertPracticeWorkflows();await W(2500);const m=document.getElementById('workflowManagerModal').classList.contains('show');return '업무 수 '+c0+'→'+app.allData.workflows.length+' | 업무 관리 열림='+m+' | 다시 그리면 '+(await after())")
